module hill_number_counter(\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] number,\n    input [3:0] digit_count,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE      = 4'd0;\n    localparam [3:0] CHECK     = 4'd1;\n    localparam [3:0] INVALID   = 4'd8;\n    localparam [3:0] COUNT     = 4'd2;\n    localparam [3:0] COUNTING  = 4'd3;\n    localparam [3:0] FINISH    = 4'd9;\n\n    reg [3:0] state;\n    reg [3:0] digit_pos;\n    reg [3:0] current_digit;\n    reg [3:0] prev_digit;\n    reg has_fallen;\n    reg [31:0] count;\n    reg [3:0] check_pos;\n    reg is_hill;\n\n    // Digit extraction function\n    function [3:0] get_digit;\n        input [31:0] packed_num;\n        input [3:0] pos;\n        begin\n            get_digit = (packed_num >> (pos * 4)) & 4'hF;\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            count <= 32'd0;\n            digit_pos <= 4'd0;\n            has_fallen <= 1'b0;\n            check_pos <= 4'd0;\n            is_hill <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= CHECK;\n                        digit_pos <= 4'd1;\n                        has_fallen <= 1'b0;\n                        is_hill <= 1'b0;\n                        count <= 32'd0;\n                    end\n                end\n                \n                CHECK: begin\n                    if (digit_pos < digit_count) begin\n                        // Get current and previous digits\n                        current_digit <= get_digit(number, digit_pos);\n                        prev_digit <= get_digit(number, digit_pos - 4'd1);\n                    end\n                    \n                    if (digit_pos < digit_count) begin\n                        if (digit_pos != 4'd0) begin\n                            if (current_digit > prev_digit) begin\n                                if (has_fallen) begin\n                                    state <= INVALID;\n                                end\n                            end else if (current_digit < prev_digit && !has_fallen) begin\n                                has_fallen <= 1'b1;\n                            end\n                        end\n                        digit_pos <= digit_pos + 4'd1;\n                    end else begin\n                        is_hill <= 1'b1;\n                        state <= COUNT;\n                        check_pos <= 4'd0;\n                    end\n                end\n                \n                INVALID: begin\n                    result <= 32'hFFFFFFFF;\n                    done <= 1'b1;\n                    state <= FINISH;\n                end\n                \n                COUNT: begin\n                    // Simplified counting logic\n                    if (is_hill) begin\n                        count <= count + 32'd1;\n                        check_pos <= check_pos + 4'd1;\n                    end\n                    \n                    if (check_pos == 4'd8) begin\n                        result <= count;\n                        done <= 1'b1;\n                        state <= FINISH;\n                    end else begin\n                        state <= COUNTING;\n                    end\n                end\n                \n                COUNTING: begin\n                    // Placeholder logic for counting\n                    count <= count + 32'd1;\n                    state <= COUNT;\n                    check_pos <= check_pos + 4'd1;\n                end\n                \n                FINISH: begin\n                    if (!start) begin\n                        done <= 1'b0;\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule